String* ShaderGlobalsOverride::_remap(const String& p_name) const
{
	String* r = param_remaps.getptr(p_name);
	if (!r) {
		// not cached, do caching
		String p = p_name;
		if (p.begins_with("params/")) {
			String q = p.replace_first("params/", "");
			param_remaps[p] = q;
			r = param_remaps.getptr(p);
		}
	}

	return r;
}

