AnimationNodeBlendNode::AnimationNodeBlendNode(NodeType p_type, bool p_three_way)
	: node_type(p_type), three_way(p_three_way)
{
	switch (node_type) {
	case NODE_ANIMATION: {
		root_node = true;
	} break;
	case NODE_ONESHOT: {
		add_input("in");
		add_input("shot");
	} break;
	case NODE_ADD: {
		if (three_way) {
			add_input("-add");
			add_input("in");
			add_input("+add");
		}
		else {
			add_input("in");
			add_input("add");
		}
	} break;
	case NODE_BLEND: {
		if (three_way) {
			add_input("-blend");
			add_input("in");
			add_input("+blend");
		}
		else {
			add_input("in");
			add_input("blend");
		}
	} break;
	case NODE_SUB: {
		add_input("in");
		add_input("sub");
	} break;
	case NODE_TIME_SCALE:
	case NODE_TIME_SEEK: {
		add_input("in");
	} break;
	case NODE_TRANSITION:
		break;
	case NODE_OUTPUT: {
		add_input("output");
	} break;
	}
}

